# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines

def shift(worker, day, start, end):
    return Shift(worker, day, Span(start * 60, end * 60))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [shift("Ana", "mon", 9, 10), shift("Brisa", "mon", 9, 13)]
        shifts.append(shift("Brisa", "tue", 9, 12))
        lines = timesheet_lines(shifts)
        self.assertEqual(lines[0], "Brisa: 2 shifts, 7.0 hours")
        self.assertEqual(lines[1], "Ana: 1 shifts, 1.0 hours")

    def test_one_decimal_place(self):
        shifts = [Shift("Ana", "mon", Span(540, 620))]
        self.assertEqual(timesheet_lines(shifts), ["Ana: 1 shifts, 1.3 hours"])

    def test_ties_broken_by_name(self):
        shifts = [shift("Zed", "mon", 9, 10), shift("Ana", "tue", 9, 10)]
        lines = timesheet_lines(shifts)
        self.assertTrue(lines[0].startswith("Ana"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([shift("  ", "mon", 9, 10)])
